    singer: "",
    album: "",
    year: 2015,
    lyrics: `一点滁州 四面山色
牵挽匆匆行者 流连许多
我自京华 料峭风波
而今残雪抖落 为此处客
牧笛声伴 酒旗飘着
西窗闲人 敲杯囫囵应和
无须管弦 不劳风雅陈设
该是羡慕 这浑然自得
我有明珠一颗 久被尘劳关锁
高门里端坐 不辨清浊
但将明月痛饮 相忘诸般因果
莲花台上 宝相佛陀
我有明珠一颗 照破山河万朵
世间应少有 闲暇如我
觅得川流万籁 如共知交蹉跎
抱琴就坐 拨弦酬酢
行舟在水 云影随侧
疑似湖中 别有碧天高阔
倦时睡去 抛短楫任漂泊
明朝天涯 栖处满青荷
待尘尽光生 求之无多
偏就做个情痴 钟于风月半刻
三分沉吟 信口寄长歌
倘瑶宫来使 大笑辞过
偏就称个醉翁 只识泉边俗者
亭上樽前 颠倒魂魄`
