    singer: "",
    album: "",
    year: 2015,
    lyrics: `一个人一次疚愧
卧了醉转轮回
三段魂一滴泪
梦魅里我是谁
也走遍东西南北
看花开年年岁岁
也饮下风雪几杯
暖与冷会尝细微
我欲在黑夜中凋零飘飞
旧梦境却如新常文饰画眉
书记此心却能数清错与对
转瞬间为事与愿违
愿语间死生观死怼
风破碎人心枯萎
吹散了情和灰
春伶仃雪玷黑
长满了伤与悲
谁给我人生中唯一称谓
谁给我个角色让我去成为
谁给我次机会掀命运幕帷
故事结尾事与愿违
梦醒在人声鼎沸`
