它叫做求不得
你来自云端
跌入人间风波
温柔了长夜梦
又消逝成泡沫
是青空白鸟
一生一次路过
多年后我已鬓如雪
而你还如昨
那阵春风
谁的笑涡
我怀念什么
是谁像微光萤火
无意间照亮过我
酒暖血热
谁曾低和
让我沉醉过
怕光阴来时无多
不为谁靠岸停泊
那时风停了
我唱着那首歌
求不得又如何
