    singer: "",
    album: "",
    year: 2021,
    lyrics: `我不愿月色皎洁
使我原形毕现
黑夜里滋生出梦魇
就悬吊在窗前
我不愿清风拂面
让人无从遮掩
欲念里挣脱出的念
惹来蚊蝇盘旋
我不愿年复一年 苟活的时间
都跌落在暗室墙沿 懒得去收捡
我不愿百种人间 复杂的善变
像每个不祥的预言 都一一应验
有哪位观众来替我解一解心结
还是要等到最后 告别再送花圈
把你的烛光喜宴来借我点根烟
你看我欠不欠个 生疏的吻别
谢幕后我看着灯光一盏盏熄灭
无人处再度出演 无人观赏的废片
沉默或欢呼将背影定格至终点
至少我尽职尽责 做个最佳配角
我不愿表演敷衍
让它没了悬念
故事里写时过境迁
只眨了一眨眼
我不愿花好月圆
衬得我太碍眼
憎恶过的麻木肤浅
都变成我的脸
我不愿放低尊严 廉价的执念
剧情枯竭哑口无言 早无处兑现
我不愿顾影自怜 狰狞的嘴脸
愿我们别再说抱歉 在有生之年
就做个配角来投身这一出幻灭
没有人有兴趣了解 我为何要闭眼
把你的深情款款背对我不必演
你看我像不像个 乏味的音节
借转角橱窗来让我勾一勾眼线
这一幕演技炸裂 唇红齿白的妖艳
傲慢与嫉妒你亲手贴上的标签
希望我至少够格 颁个最佳配角`
