把渐渐黯淡的心念成忘
他看过好风光
喧嚣后冷清的是人生的模样
他合上戏本
黑暗中坐到天亮
台上人字句铿锵
台下人笑泪满腔
演真假悲欢几场
别说谁不配妄想
不看不听不自量
谁又是天生懂炎凉
如果曾寸步不让
会不会真有月光
穿云破雾仍明亮
如果爱沦为虚妄
